"""Render the bounded research results without changing any model result."""
from pathlib import Path
import json,html,zipfile,hashlib
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

NAMES={'equal_weight':'Equal weight','raw_mean_variance':'Raw MV','cash_reserve':'Simple cash reserve','cash_fixed_property':'Cash + fixed property','cara_constraints':'CARA, same constraints','mv_same_constraints':'MV, same constraints','whole_fit_bagging':'Whole-fit bagging'}
ROOT=Path('artifacts/robustness-20261107')


def read(name):
    p=ROOT/(name+'.json');return json.loads(p.read_text()) if p.exists() else None


def fmt(x):return f'{x*100:+.2f}%'


def annual_table(data,model):
    if not data:return []
    rows=[]
    for method in ['cash_fixed_property:raw','raw_mean_variance:validation_calibrated','cara_constraints:validation_calibrated','mv_same_constraints:validation_calibrated','whole_fit_bagging:validation_calibrated']:
        records=[]
        for year in data['origins']:
            row=next((x for x in year.get('rows',[]) if x['method']==method),None)
            if row:records.append(dict(origin=year['origin'],**row))
        if not records:continue
        returns=[x['ledger_net_return'] for x in records];rows.append(dict(model=model,method=method,name=NAMES[method.split(':')[0]],count=len(records),mean=float(np.mean(returns)),worst=float(min(returns)),funded=sum(x['funded'] for x in records),final_pass=sum(x['model_final_pass'] for x in records),records=records))
    return rows


def build():
    out=ROOT/'report';out.mkdir(parents=True,exist_ok=True)
    pilot=read('pilot');higher=read('higher-fidelity');bag=read('resample32');fhs=read('fhs');sens=read('sensitivity');annual=annual_table(read('annual-walkforward'),'Gaussian mixture')+annual_table(read('annual-fhs'),'EWMA FHS')+annual_table(read('annual-bagging'),'Mixture + outer refit')
    summary=dict(pilot_seconds=pilot['wall_seconds'],higher_seconds=higher['seconds'],bag_success=bag['statuses']['whole_fit_bagging']['successful'],bag_required=bag['statuses']['whole_fit_bagging']['required'],annual=annual,radius=pilot['radius_diagnostic'],sources='ROBUSTNESS_SOURCES.md',limits=['Private research, not a recommendation.','Conditional simulated judge is not economic truth.','Annual episodes reset capital, include3% scheduled withdrawals and do not form a compounded strategy.','Latest data vintages, assumed 45-day property release lag, not revision-safe point-in-time archives.','Cash earns0% by explicit uncalibrated assumption.','Listed sales assumed immediately spendable within each week.','W1 radius remains uncalibrated. Ledger is not W1-certified.','Separate quarterly bootstrap refits property dispersion, but does not estimate joint cross-frequency dependence.'])
    (out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
    plt.rcParams.update({'figure.facecolor':'#0d1117','axes.facecolor':'#0d1117','axes.edgecolor':'#28323f','axes.labelcolor':'#dce5ef','xtick.color':'#b7c0ce','ytick.color':'#b7c0ce','text.color':'#dce5ef','font.family':'DejaVu Sans','font.size':10})
    fig,ax=plt.subplots(figsize=(10,4.4));palette=['#4fe3c1','#6fa8ff','#c49cf0'];base='cara_constraints:validation_calibrated'
    for i,model in enumerate(['Gaussian mixture','EWMA FHS','Mixture + outer refit']):
        row=next((x for x in annual if x['model']==model and x['method']==('whole_fit_bagging:validation_calibrated' if 'refit' in model else base)),None)
        if row:ax.plot([int(x['origin'][:4])+1 for x in row['records']],[x['ledger_net_return']*100 for x in row['records']],marker='o',markersize=3,label=model,color=palette[i])
    ax.axhline(0,color='#566170',linewidth=.7);ax.axhline(-3,color='#f2b24c',linewidth=.8,linestyle='--',label='-3%: annual withdrawals alone, before property changes');ax.set_ylabel('End wealth change after payouts (%)');ax.set_xlabel('Holdout episode year');ax.grid(alpha=.12);ax.legend(loc='best',fontsize=8);fig.tight_layout();fig.savefig(out/'annual-episodes.svg');plt.close(fig)
    # Same-constraint model objectives, trained identically, conditional judge.
    pairs=[]
    for label,data in [('Higher-fidelity mixture',higher),('Outer32 mixture',bag),('EWMA FHS',fhs)]:
        for row in data['rows']:
            if row['method'] in ['cara_constraints:validation_calibrated','mv_same_constraints:validation_calibrated','whole_fit_bagging:validation_calibrated']:
                pairs.append(dict(study=label,name=NAMES[row['method'].split(':')[0]],ce=row['ledger']['net_ce_mean']/1e6,passed=row['final']['overall_pass'],fraction=row['calibrated_fraction']))
    def cards(rows,fields):
        return ''.join('<div class="record">'+''.join(f'<div><span>{html.escape(label)}</span><strong>{html.escape(str(fun(row)))}</strong></div>' for label,fun in fields)+'</div>' for row in rows)
    annualcards=cards(annual,[('Model',lambda r:r['model']),('Policy',lambda r:r['name']),('Episodes',lambda r:r['count']),('Mean wealth change after payouts',lambda r:fmt(r['mean'])),('Worst episode',lambda r:fmt(r['worst'])),('All payments made',lambda r:f"{r['funded']} / {r['count']}"),('Final model checks passed',lambda r:f"{r['final_pass']} / {r['count']}")])
    pairedcards=cards(pairs,[('Study',lambda r:r['study']),('Policy',lambda r:r['name']),('Ledger certainty equivalent',lambda r:f"${r['ce']:.3f}M"),('Fraction of raw candidate after validation',lambda r:f"{r['fraction']:.2f}"),('Independent final model check',lambda r:'PASS' if r['passed'] else 'FAIL')])
    sensitivity=[]
    for case in sens['cases']:
        if 'error'in case:continue
        c=case['config'];status=case['statuses']['cara_constraints'];raw=next((x for x in case['rows'] if x['method']=='cara_constraints:raw'),None);cal=next((x for x in case['rows'] if x['method']=='cara_constraints:validation_calibrated'),None)
        sensitivity.append(dict(paths=c['train_scenarios'],seed=c['seed'],radius=c['wasserstein_radius'],status=status['kind'],raw='not returned' if raw is None else 'PASS' if raw['final']['overall_pass'] else 'FAIL',cal='not returned' if cal is None else 'PASS' if cal['final']['overall_pass'] else 'FAIL'))
    sensitivitycards=cards(sensitivity,[('Train paths / seed',lambda r:f"{r['paths']} / {r['seed']}"),('W1 radius',lambda r:r['radius']),('Numerical status',lambda r:r['status']),('Raw final checks',lambda r:r['raw']),('Validation-calibrated final checks',lambda r:r['cal'])])
    stress=read('payout-stress');stressrows=[]
    for case in stress['cases']:
        row=next((r for r in case.get('study',{}).get('rows',[]) if r['method']=='cara_constraints:validation_calibrated'),None)
        if row:stressrows.append(dict(name=case['name'],passed=row['final']['overall_pass'],paid=row['ledger']['funded_probability_mean'],gap=row['ledger']['max_payment_tail_gap']))
    stresscards=cards(stressrows,[('Counterfactual schedule',lambda r:r['name'].replace('M','M ').replace('plus','plus ')),('Declared model limits',lambda r:'PASS' if r['passed'] else 'FAIL'),('Reference paths making every payment',lambda r:f"{r['paid']*100:.1f}%"),('Largest batch tail-average unpaid amount',lambda r:f"${r['gap']/1e6:.2f}M")])
    scope=''.join('<li>'+html.escape(x)+'</li>' for x in summary['limits'])
    bagcount=summary['bag_success'];required=summary['bag_required']
    text=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ballast research checks ·7 November 2026</title><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#090d12;color:#dce5ef;font:15px/1.65 system-ui,sans-serif}}main{{max-width:1080px;margin:auto;padding:34px 22px 70px}}h1,h2{{line-height:1.2}}h1{{font-size:38px;margin:12px 0 20px}}h2{{font-size:25px}}a{{color:#4fe3c1}}.eyebrow{{font:11px monospace;letter-spacing:.15em;color:#4fe3c1;text-transform:uppercase}}.lead{{font-size:20px;max-width:760px}}section{{padding:28px;margin:24px 0;border:1px solid #24303d;background:#0d1117;border-radius:20px}}.callout{{padding:18px;background:#1d151a;border-left:3px solid #f77878;margin:20px 0}}.muted,span{{color:#a8b6c8}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}.stats>div{{background:#0d1117;border:1px solid #24303d;padding:20px;border-radius:14px}}.num{{font-size:30px;color:#4fe3c1;font-weight:600}}.records{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}}.record{{padding:18px;background:#090d12;border:1px solid #24303d;border-radius:12px}}.record>div{{display:flex;justify-content:space-between;gap:18px;border-bottom:1px solid #1b2430;padding:6px 0;font-size:13px}}.record span{{max-width:60%}}.record strong{{text-align:right}}img{{width:100%;height:auto}}li{{margin:10px 0}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:22px}}small{{display:block;color:#a8b6c8}}@media(max-width:650px){{main{{padding:24px 14px 50px}}h1{{font-size:29px}}section{{padding:20px 16px}}.stats,.records,.two{{grid-template-columns:1fr}}.record>div{{flex-direction:column;gap:2px}}.record span{{max-width:none}}.record strong{{text-align:left}}.lead{{font-size:18px}}}}@media print{{body{{background:white;color:#111;font-size:13px;line-height:1.5}}section{{break-inside:auto!important;margin:16px 0;padding:18px}}h2,h3{{break-after:avoid}}.record,.callout,li{{break-inside:avoid}}.record>div{{font-size:12px}}.lead{{font-size:17px}}section,.record,.stats>div{{background:white;border-color:#ddd;break-inside:avoid}}span,small,.muted{{color:#444}}a,.eyebrow,.num{{color:#15695b}}.callout{{background:#fff0f0}}main{{padding:10px;max-width:none}}footer{{display:none}}h1{{font-size:28px}}}}
    </style></head><body><main><div class="eyebrow">Ballast / private research /7 November 2026</div><h1>Better foundations.<br>No shortcut to a safety claim.</h1><p class="lead">Finite-moment scenarios, a separate all-risk judge, an executable cash-first audit and matched historical tests are now in place. These tests show where the model fails as well as where it passes.</p><div class="stats"><div><span>Annual holdouts</span><div class="num">19</div><small>2007-2025, fixed-policy episodes</small></div><div><span>Outer refits succeeded</span><div class="num">{bagcount}/{required}</div><small>All required; failed fits would not be silently dropped</small></div><div><span>Recommendation status</span><div class="num">Research</div><small>No investment recommendation or coverage guarantee</small></div></div>
    <div class="callout"><strong>A funding-budget pass is not a paid-in-full promise.</strong><p>The configured rule allows a 20% tail-shortfall budget. In a counterfactual $95M final call, a cash-plus-property portfolio can pass that allowance while missing $5M on every path because the fixed property is unsold. This is a limit of the chosen rule, not a changed commitment or the default $3M schedule.</p></div><section><div class="eyebrow">01 / What changed</div><h2>Fix the meaning before comparing the numbers.</h2><div class="two"><div><h3>Model and risk</h3><ul><li>Unbounded log-Student-t was replaced in the default by an explicit Gaussian variance mixture. Price moments are finite; parameters remain development choices.</li><li>A final funding pass no longer means an all-risk pass. Every payment, path/terminal loss, holdings and finite posterior hull are checked on frozen final scenarios.</li><li>Unvalidated stochastic calls are disabled. Final edited inputs meet one validation boundary.</li></ul></div><div><h3>Accounting and robustness</h3><ul><li>Cash-first sales are recorded in a separate units/cash ledger. A hand example produces 98 versus 100 under provisioning. The optimizer has not been relabelled a dynamic trading policy.</li><li>The W1 metric is invariant to splitting an identical sleeve and repeating dates. The radius is still uncalibrated.</li><li>Property annual dispersion uses four-quarter sums including serial covariance. Weekly dependence remains assumed.</li></ul></div></div></section>
    <section><div class="eyebrow">02 / Matched judge</div><h2>A fair comparison can still be inconclusive.</h2><p>Each method gets the same fixed validation and final judge, holdings constraints and cash-anchor calibration choices. The judge model is the Gaussian mixture, even for FHS-trained candidates. FHS is therefore not graded against a friendlier self-created truth. Final results never trigger a repair.</p><p>Higher-fidelity pilot: 800 training /1200 validation /2400 final scenarios,8 batches. Outer-refit and FHS pilots use 200 /400 /800 with4 batches. The values below are conditional cash-ledger certainty equivalents, not expected wealth or established economic performance.</p><div class="records">{pairedcards}</div><div class="callout">CARA and same-constraint MV are very close here. Averaging refitted portfolios is not guaranteed to help; no method is declared best from these tests. A pass means only the declared conditional model checks passed, not that future withdrawals or capital are safe.</div></section>
    <section><div class="eyebrow">03 / Actual held-out history</div><h2>Annual episodes include 2008, 2020 and 2022.</h2><p>Fit uses only past ETF/FX rows and property quarters available under an assumed 45-day release lag. All policies face identical future history and the same cash-first rule. Capital resets to $100M each episode; there are $3M scheduled withdrawals. These are not compounded strategy returns. Negative wealth change includes the withdrawals, not just investment loss.</p><img src="annual-episodes.svg" alt="Annual net-wealth changes after withdrawals under matched fixed-policy historical episodes"><p class="muted">Crisis dates were chosen as descriptive stress episodes, not as an independent confirmation set. Latest data vintages can revise the past. Zero missed payments with large cash holdings and a 3% withdrawal schedule is not strong tail-risk evidence.</p><div class="records">{annualcards}</div></section>
    <section><div class="eyebrow">04 / Sensitivity</div><h2>Numerical success is not a statistical pass.</h2><p>The reduced matrix is fixed in advance, not searched for the best-looking result. A radius 0.00004 implies an unavoidable $80,000 sufficient funding buffer on$100M, above the $50,000 per-payment budget. The engine reports that conflict instead of relaxing risk checks.</p><div class="records">{sensitivitycards}</div><div class="callout">A past earlier-versus-recent empirical path-distribution discrepancy was {summary['radius']['distance']:.3f}, compared with the illustrative radius 0.00002. This is NOT a calibrated replacement radius or a coverage estimate: it mixes genuine regime change and sampling variation, omits property/liabilities and uses only 21 annual blocks. It shows why the tiny configured radius cannot be called statistically validated.</div></section>
    <section><div class="eyebrow">05 / Funding stress</div><h2>Make the gap between a risk budget and full payment visible.</h2><p>These are declared counterfactual schedules, not user obligations. The $3M default is unchanged. Funding allows tail shortfalls equal to 20% of each payment; it is not a minimum probability of making all payments. The same cash-first ledger audits each candidate independently.</p><div class="records">{stresscards}</div><p>A $60M early call plus $30M final call makes every payment on only about 84% of reference paths in a candidate that passes the declared model limits. The $95M example can pass with near-universal missed payments. A strict paid-in-full requirement would need a different funded-policy specification, not friendlier labels or thresholds.</p></section><section><div class="eyebrow">06 / Limits and next tests</div><h2>What still prevents a stronger claim.</h2><ul>{scope}</ul><p>Next useful work: genuine point-in-time property vintages and publication calendars, calibrated cash carry and sale settlement, joint quarterly property/ETF/FX dependence, more outer replications and prespecified rolling radius selection. Dynamic-policy optimization is a separate model extension, not a cosmetic ledger change.</p><p>Method sources: stationary/block bootstrap, portfolio estimation-risk research, Wasserstein/Lipschitz bounds, and FHS authors plus Federal Reserve cautions. See the accompanying source ledger and machine-readable evidence. No source code was copied from the cited papers.</p><h3>Method sources</h3><ul><li><a href="https://www.newfrontieradvisors.com/media/rxbld4hq/estimation-error-and-portfolio-optimization-12-05.pdf">Michaud &amp; Michaud: estimation error and portfolio resampling</a>. Motivation for outer refits, not a universal benefit claim.</li><li><a href="https://www.jstage.jst.go.jp/article/jjss/40/2/40_2_189/_pdf/-char/en">Stationary-return portfolio estimation-risk research</a>. Dependent returns need more than iid parameter draws.</li><li><a href="https://www.tandfonline.com/doi/abs/10.1080/01621459.1994.10476870">Politis &amp; Romano: stationary bootstrap</a>. Geometric-length blocks; stationarity assumptions remain a limitation.</li><li><a href="https://link.springer.com/article/10.1007/s10107-017-1172-1">Esfahani &amp; Kuhn: Wasserstein data-driven robustness</a>. Sufficient transport bounds do not validate an arbitrary chosen radius.</li><li><a href="https://www.filteredhistoricalsimulation.com/history-of-fhs.php">FHS authors: methodology and history</a>. Our EWMA variant is not a fitted GARCH replication.</li><li><a href="https://www.federalreserve.gov/Pubs/feds/2001/200127/200127pap.pdf">Federal Reserve: Hidden Dangers of Historical Simulation</a>. Changing correlations and short tail samples can defeat apparent robustness.</li></ul></section><footer class="muted">Private research. Generated from saved JSON results; source/config/data hashes and solver statuses stay with the evidence. No public hosting, client data, spending or external communication.</footer></main></body></html>'''
    (out/'report.html').write_text(text)
    return out

if __name__=='__main__':print(build())
